  "implementation": "def solve(case):
    import json
    nodes = case['nodes']
    core = case['core_distance']
    dist_list = case['distances']

    # Build edges with mutual reachability
    edges = []
    for u, v, d in dist_list:
        if u < v:
            a, b = u, v
        else:
            a, b = v, u
        w = max(core[u], core[v], d)
        edges.append((w, a, b))

    # Sort deterministically: weight, then node1, then node2
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    n_nodes = len(nodes)
    for w, a, b in edges:
        if union(a, b):
            mst_edges.append([a, b, w])
            total_weight += w
            if len(mst_edges) == n_nodes - 1:
                break

    # Check connectivity (should be connected)
    if len(mst_edges) != n_nodes - 1:
        raise ValueError('Graph is disconnected')

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
